import {RECIPE_CASES,RECIPE_INGREDIENTS,RECIPE_MODEL,RECIPE_PAGES,RECIPE_SUPPORT,RECIPE_UNITS,RECIPE_EXAMPLE,recipeById} from './measuring-recipes-content.mjs';
import {localDay,validDay} from './town-day.mjs';
const IDS=RECIPE_INGREDIENTS.map(i=>i.id),TYPES=['reading','tray'];
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
const clone=x=>JSON.parse(JSON.stringify(x));
// Saved recipe sources are matched on ids and amounts, not display wording, so a copy edit cannot strand a save.
const wordless=x=>JSON.parse(JSON.stringify(x,(k,v)=>['title','purpose','notice','details'].includes(k)?undefined:v));
const amount=(n,max=500)=>Number.isSafeInteger(n)&&n>=0&&n<=max&&n%50===0;
function same(a,b){if(a===b)return true;if(Array.isArray(a)||Array.isArray(b))return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>same(v,b[i]));return object(a)&&object(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&same(a[k],b[k]));}
const supportValid=s=>object(s)&&s.visual===true&&Object.entries(s).every(([k,v])=>RECIPE_SUPPORT.includes(k)&&v===true);
const readingValid=r=>keys(r,['text','unit'])&&typeof r.text==='string'&&r.text.length<=24&&(r.unit===null||RECIPE_UNITS.includes(r.unit));
export function parseRecipeReading(text){if(typeof text!=='string'||text.length>24||!/^\d+$/.test(text.trim()))return null;const n=Number(text.trim());return Number.isSafeInteger(n)&&n>=0&&n<=500?n:null;}
export function recipeSources(model){return Object.fromEntries(IDS.map(id=>[id,1000-model.portions[id]-(model.jug.ingredient===id?model.jug.amount:0)]));}
function modelValid(m){return keys(m,['jug','portions'])&&keys(m.jug,['ingredient','amount'])&&amount(m.jug.amount)&&(m.jug.amount===0?m.jug.ingredient===null:IDS.includes(m.jug.ingredient))&&keys(m.portions,IDS)&&IDS.every(id=>amount(m.portions[id]))&&Object.values(recipeSources(m)).every(n=>amount(n,1000));}
const apparatusValid=(m,selected)=>modelValid(m)&&IDS.includes(selected)&&(m.jug.amount===0||m.jug.ingredient===selected);
export function recipeReadingAssessment(model,reading){const readNumber=parseRecipeReading(reading.text);return readNumber===null?null:{readNumber,actualAmount:model.jug.amount,numberRead:readNumber===model.jug.amount,unitNamed:reading.unit==='mL'};}
export function recipeTrayAssessment(c,model){const ingredients=Object.fromEntries(IDS.map(id=>{const amount=model.portions[id],target=c.targets[id];return [id,{amount,target,status:amount<target?'below':amount>target?'above':'matches'}];})),portionsMatch=IDS.every(id=>ingredients[id].status==='matches'),jugEmpty=model.jug.amount===0;return {ingredients,portionsMatch,jugEmpty,ready:portionsMatch&&jugEmpty};}
// Saved results are checked for their amounts and outcomes, not re-graded, so changing how results are computed or shaped cannot lock saved work.
const trayValid=a=>object(a)&&object(a.ingredients)&&IDS.every(id=>object(a.ingredients[id])&&amount(a.ingredients[id].amount)&&amount(a.ingredients[id].target)&&['below','above','matches'].includes(a.ingredients[id].status))&&['portionsMatch','jugEmpty','ready'].every(k=>typeof a[k]==='boolean');
function snapshotValid(c,s){if(!object(s)||!TYPES.includes(s.kind)||!keys(s,['kind','source','selectedIngredient','model','assessment','support','familiar','practice','visual'],s.kind==='reading'?['reading']:[])||!same(wordless(s.source),wordless(c))||!apparatusValid(s.model,s.selectedIngredient)||!supportValid(s.support)||typeof s.familiar!=='boolean'||s.practice!==true||s.visual!==true)return false;return s.kind==='reading'?readingValid(s.reading)&&parseRecipeReading(s.reading.text)!==null&&object(s.assessment)&&amount(s.assessment.actualAmount)&&typeof s.assessment.numberRead==='boolean'&&typeof s.assessment.unitNamed==='boolean':trayValid(s.assessment);}
function keptValid(c,k){return keys(k,['source','selectedIngredient','model','reading','readingStale','assessment','support','familiar','practice','visual'],['latestReading','latestTray','keptDay'])&&(!Object.hasOwn(k,'keptDay')||validDay(k.keptDay))&&same(wordless(k.source),wordless(c))&&apparatusValid(k.model,k.selectedIngredient)&&readingValid(k.reading)&&typeof k.readingStale==='boolean'&&trayValid(k.assessment)&&supportValid(k.support)&&typeof k.familiar==='boolean'&&k.practice===true&&k.visual===true&&(!Object.hasOwn(k,'latestReading')||object(k.latestReading)&&k.latestReading.kind==='reading'&&snapshotValid(c,k.latestReading))&&(!Object.hasOwn(k,'latestTray')||object(k.latestTray)&&k.latestTray.kind==='tray'&&snapshotValid(c,k.latestTray));}
const latest=(w,kind)=>w.checks.findLast(s=>s.kind===kind)||null;
const MESSAGES=['','jug-returned','portion-returned','all-returned'];
function workValid(c,w){
 if(!keys(w,['source','selectedIngredient','model','reading','readingStale','feedback','inputError','support','seen','familiar','exampleStep','checks','kept','message'])||!same(wordless(w.source),wordless(c))||!apparatusValid(w.model,w.selectedIngredient)||!readingValid(w.reading)||typeof w.readingStale!=='boolean'||!keys(w.feedback,['reading','tray'])||!TYPES.every(k=>typeof w.feedback[k]==='boolean')||!['','reading-invalid'].includes(w.inputError)||!supportValid(w.support)||w.seen!==true||typeof w.familiar!=='boolean'||!(w.exampleStep===null||Number.isSafeInteger(w.exampleStep)&&w.exampleStep>=0&&w.exampleStep<=8&&w.support.workedExample===true)||!Array.isArray(w.checks)||w.checks.length>24||!w.checks.every(s=>snapshotValid(c,s))||!(w.kept===null||keptValid(c,w.kept))||!MESSAGES.includes(w.message))return false;
 const r=latest(w,'reading'),t=latest(w,'tray');
 return (!w.feedback.reading||r&&same(r.source,w.source)&&same(r.model,w.model)&&same(r.reading,w.reading)&&!w.readingStale&&w.inputError==='')&&(!w.feedback.tray||t&&same(t.source,w.source)&&same(t.model,w.model))&&(w.inputError!=='reading-invalid'||parseRecipeReading(w.reading.text)===null&&!w.feedback.reading)&&(!w.readingStale||w.reading.text!==''||w.reading.unit!==null);
}
function valid(r){return keys(r,['version','currentCase','page','cases'],['recovered'])&&r.version===1&&RECIPE_PAGES.includes(r.page)&&object(r.cases)&&Object.keys(r.cases).length<=6&&Object.entries(r.cases).every(([id,w])=>{const c=recipeById(id);return c&&workValid(c,w);})&&(r.currentCase===null||recipeById(r.currentCase)&&Object.hasOwn(r.cases,r.currentCase))&&(r.page==='choose'||r.currentCase!==null);}
const fresh=()=>({version:1,currentCase:null,page:'choose',cases:{}});
export function recipeState(state){return state.measuringRecipes===undefined?fresh():valid(state.measuringRecipes)?state.measuringRecipes:null;}
export function ensureRecipes(state){if(state.measuringRecipes===undefined)state.measuringRecipes=fresh();return recipeState(state);}
export function recoverRecipes(state){if(state.measuringRecipes===undefined||recipeState(state))return false;const original=state.measuringRecipes,cases=Object.entries(object(original?.cases)?original.cases:{}).filter(([id,w])=>recipeById(id)&&workValid(recipeById(id),w));state.measuringRecipes={...fresh(),cases:clone(Object.fromEntries(cases)),recovered:original};return true;}
function change(state,fn){const r=recipeState(state);if(!r)return false;const next=clone(r),result=fn(next);if(result===false||!valid(next))return false;state.measuringRecipes=next;return result??true;}
const work=r=>r.currentCase?r.cases[r.currentCase]:null;
const current=r=>({c:recipeById(r.currentCase),w:work(r)});
const emptyModel=()=>({jug:{ingredient:null,amount:0},portions:Object.fromEntries(IDS.map(id=>[id,0]))});
const newWork=c=>({source:clone(c),selectedIngredient:IDS[0],model:emptyModel(),reading:{text:'',unit:null},readingStale:false,feedback:{reading:false,tray:false},inputError:'',support:{visual:true},seen:true,familiar:false,exampleStep:null,checks:[],kept:null,message:''});
export function chooseRecipe(state,id){const c=recipeById(id);if(!c)return false;return change(state,r=>{if(Object.hasOwn(r.cases,id))r.cases[id].familiar=true;else r.cases[id]=newWork(c);r.currentCase=id;r.page='measure';});}
export function nextRecipe(state){const r=recipeState(state);return r?chooseRecipe(state,RECIPE_CASES[(RECIPE_CASES.findIndex(c=>c.id===r.currentCase)+1)%6].id):false;}
export function setRecipePage(state,page){if(!RECIPE_PAGES.includes(page))return false;return change(state,r=>{if(page!=='choose'&&!work(r))return false;r.page=page;});}
export function chooseRecipeIngredient(state,id){if(!IDS.includes(id))return false;return change(state,r=>{const w=work(r);if(!w||w.selectedIngredient===id||w.model.jug.amount>0)return false;w.selectedIngredient=id;w.message='';});}
function manipulated(w,oldJug,message=''){w.support.handling=true;w.feedback.tray=false;w.feedback.reading=false;w.message=message;if(!same(w.model.jug,oldJug)){w.feedback.reading=false;w.inputError='';w.readingStale=w.reading.text!==''||w.reading.unit!==null;}}
export function fillRecipeJug(state){return change(state,r=>{const w=work(r);if(!w||w.model.jug.amount+50>500||recipeSources(w.model)[w.selectedIngredient]<50||w.model.jug.amount>0&&w.model.jug.ingredient!==w.selectedIngredient)return false;const old=clone(w.model.jug);w.model.jug={ingredient:w.selectedIngredient,amount:w.model.jug.amount+50};manipulated(w,old);});}
export function returnRecipeJug(state,all=false){if(typeof all!=='boolean')return false;return change(state,r=>{const w=work(r);if(!w||w.model.jug.amount===0)return false;const old=clone(w.model.jug),n=all?w.model.jug.amount:50;w.model.jug.amount-=n;if(w.model.jug.amount===0)w.model.jug.ingredient=null;manipulated(w,old,all?'jug-returned':'');});}
export function pourRecipeJug(state){return change(state,r=>{const w=work(r);if(!w||w.model.jug.amount===0)return false;const id=w.model.jug.ingredient;if(w.model.portions[id]+w.model.jug.amount>500)return false;const old=clone(w.model.jug);w.model.portions[id]+=w.model.jug.amount;w.model.jug={ingredient:null,amount:0};manipulated(w,old);});}
export function returnRecipePortion(state,id,all=false){if(!IDS.includes(id)||typeof all!=='boolean')return false;return change(state,r=>{const w=work(r);if(!w||w.model.portions[id]===0)return false;const old=clone(w.model.jug);if(all){w.model.portions[id]=0;manipulated(w,old,'portion-returned');}else{if(w.model.jug.amount+50>500||w.model.jug.amount>0&&w.model.jug.ingredient!==id)return false;w.model.portions[id]-=50;w.model.jug={ingredient:id,amount:w.model.jug.amount+50};w.selectedIngredient=id;manipulated(w,old);} });}
export function resetRecipeApparatus(state){return change(state,r=>{const w=work(r);if(!w||w.model.jug.amount===0&&IDS.every(id=>w.model.portions[id]===0))return false;const old=clone(w.model.jug);w.model=emptyModel();manipulated(w,old,'all-returned');});}
export function setRecipeReading(state,text){if(typeof text!=='string'||text.length>24)return false;return change(state,r=>{const w=work(r);if(!w)return false;w.reading.text=text;w.feedback.reading=false;w.inputError='';if(text===''&&w.reading.unit===null)w.readingStale=false;});}
export function setRecipeUnit(state,unit){if(unit!==null&&!RECIPE_UNITS.includes(unit))return false;return change(state,r=>{const w=work(r);if(!w)return false;w.reading.unit=unit;w.feedback.reading=false;w.inputError='';if(w.reading.text===''&&unit===null)w.readingStale=false;});}
export function useRecipeSupport(state,kind){if(!RECIPE_SUPPORT.includes(kind)||['visual','handling','readingFeedback','trayFeedback'].includes(kind))return false;return change(state,r=>{const w=work(r);if(!w)return false;w.support[kind]=true;if(kind==='workedExample'&&w.exampleStep===null)w.exampleStep=0;});}
export function stepRecipeExample(state,delta){if(![-1,1].includes(delta))return false;return change(state,r=>{const w=work(r);if(!w)return false;w.support.workedExample=true;w.exampleStep=Math.max(0,Math.min(8,(w.exampleStep??0)+delta));});}
function snapshot(c,w,kind){return {kind,source:clone(w.source),selectedIngredient:w.selectedIngredient,model:clone(w.model),...(kind==='reading'?{reading:clone(w.reading)}:{}),assessment:kind==='reading'?recipeReadingAssessment(w.model,w.reading):recipeTrayAssessment(c,w.model),support:clone(w.support),familiar:w.familiar||w.checks.some(x=>x.kind===kind),practice:true,visual:true};}
function pushCheck(w,s){w.checks.push(s);while(w.checks.length>24){const redundant=w.checks.findIndex((old,i)=>w.checks.slice(i+1).some(next=>next.kind===old.kind));w.checks.splice(redundant,1);}}
export function checkRecipeReading(state){return change(state,r=>{const {c,w}=current(r);if(!w)return false;if(parseRecipeReading(w.reading.text)===null){w.feedback.reading=false;w.inputError='reading-invalid';return {valid:false,error:'Use a whole number from 0 to 500. A blank entry is still a draft.'};}const s=snapshot(c,w,'reading');pushCheck(w,s);w.support.readingFeedback=true;w.support.readingReveal=true;w.feedback.reading=true;w.readingStale=false;w.inputError='';return clone(s);});}
export function checkRecipeTray(state){return change(state,r=>{const {c,w}=current(r);if(!w)return false;const s=snapshot(c,w,'tray');pushCheck(w,s);w.support.trayFeedback=true;w.feedback.tray=true;return clone(s);});}
export function keepRecipe(state){return change(state,r=>{const {c,w}=current(r);if(!w)return false;w.kept={source:clone(w.source),selectedIngredient:w.selectedIngredient,model:clone(w.model),reading:clone(w.reading),readingStale:w.readingStale,assessment:recipeTrayAssessment(c,w.model),support:clone(w.support),familiar:w.familiar,practice:true,visual:true,keptDay:localDay()};for(const kind of TYPES){const s=latest(w,kind);if(s)w.kept[kind==='reading'?'latestReading':'latestTray']=clone(s);}return clone(w.kept);});}
export function recipeExample(step){return Number.isSafeInteger(step)&&step>=0&&step<=8?{...RECIPE_EXAMPLE,step,amount:step*50,complete:step===8}:null;}
export function recipeScale(amount){return Number.isSafeInteger(amount)&&amount>=0&&amount<=500&&amount%50===0?{amount,capacity:500,unit:'mL',levelFraction:amount/500,ticks:Array.from({length:11},(_,i)=>({amount:i*50,levelFraction:i/10,major:i%2===0,label:i%2===0?String(i*50):null}))}:null;}
export function recipeReadingFeedback(s){if(!s||s.kind!=='reading')return '';return `${s.assessment.numberRead?'That number matches':'That number differs from'} the jug’s ${s.assessment.actualAmount} mL level. ${s.assessment.unitNamed?'mL names the volume unit on this scale.':'This scale measures liquid volume in mL (millilitres). Choose mL; g names mass and items counts objects.'}`;}
export function recipeTrayFeedback(s){if(!s||s.kind!=='tray')return '';const parts=IDS.map(id=>{const x=s.assessment.ingredients[id];return `${id}: ${x.amount} mL ${x.status==='matches'?'matches':x.status==='below'?'is below':'is above'} the ${x.target} mL request.`;});parts.push(s.assessment.ready?'Both preparation jars match and the jug is empty: the pictured tray is ready to set out.':s.assessment.portionsMatch?'Both preparation jars match. Extra liquid is still in the jug; return it before setting out the pictured tray.':'The jug stays separate from the two preparation amounts. You can change or keep this draft.');return parts.join(' ');}
export function recipeView(state){const r=recipeState(state);if(!r)return null;const {c,w}=current(r);if(!w)return {case:null,work:null};const model=w.model,jug=model.jug,sources=recipeSources(model),assessment=recipeTrayAssessment(c,model);
 const actions={fill:{enabled:jug.amount<500&&sources[w.selectedIngredient]>=50,reason:jug.amount===500?'The jug is at its 500 mL capacity.':sources[w.selectedIngredient]<50?'This source does not have 50 mL available.':''},returnJug:{enabled:jug.amount>0,reason:jug.amount===0?'The jug is empty.':''},pour:{enabled:jug.amount>0&&model.portions[jug.ingredient]+jug.amount<=500,reason:jug.amount===0?'The jug is empty.':model.portions[jug.ingredient]+jug.amount>500?'That preparation jar would exceed its 500 mL capacity.':''},chooseIngredient:{enabled:jug.amount===0,reason:jug.amount>0?'Return or pour this ingredient first.':''},returnPortions:Object.fromEntries(IDS.map(id=>[id,{enabled:model.portions[id]>=50&&jug.amount<500&&(jug.amount===0||jug.ingredient===id),reason:model.portions[id]===0?'This preparation jar is empty.':jug.amount===500?'The jug is at its 500 mL capacity.':jug.amount>0&&jug.ingredient!==id?'Return or pour this ingredient first.':''}]))};
 const latestReading=latest(w,'reading'),latestTray=latest(w,'tray');
 const message=w.message==='jug-returned'?'The jug’s contents returned to their source.':w.message==='portion-returned'?'This preparation jar’s contents returned to their own source.':w.message==='all-returned'?'All current portions returned to their sources. Your reading draft, earlier checks and kept tray remain.':'';
 return {case:c,work:w,model,sources,assessment,actions,latestReading,latestTray,readingFeedback:w.feedback.reading?recipeReadingFeedback(latestReading):'',trayFeedback:w.feedback.tray?recipeTrayFeedback(latestTray):'',inputError:w.inputError==='reading-invalid'?'Use a whole number from 0 to 500. A blank entry is still a draft.':'',readingStatus:w.readingStale?'earlier draft':w.feedback.reading?'checked':'draft',scale:recipeScale(jug.amount),example:w.exampleStep===null?null:recipeExample(w.exampleStep),differences:Object.fromEntries(IDS.map(id=>[id,c.targets[id]-model.portions[id]])),message};
}
